"use client";

import * as XLSX from "xlsx";
import { ChangeEvent, type PointerEvent as ReactPointerEvent, useEffect, useMemo, useState } from "react";
import "./reconciliation.css";

type InvoiceEntry = { date: string; invoice: string; amount: string; note: string };
type LedgerLookup = Record<string,{amount:number;dates:string[]}>;
type OtherEntry = { amount: string; note: string; image?: string };
type DetailForm = { customerAmount: string; responsible: string; transit: InvoiceEntry[]; returned: InvoiceEntry[]; lost: InvoiceEntry[]; instrument: InvoiceEntry[]; otherInvoice: InvoiceEntry[]; other: OtherEntry[]; badDebt: string; badDebtReason: string; adjustment: string; adjustmentReason: string; resolutionSolution: string; resolutionTime: string };
type LocalSheet = { headers: string[]; rows: unknown[][]; fileName: string; details?: Record<string, DetailForm> };
type LedgerUpload = { keys: string[]; fileNames: string[]; updatedAt: string };

const T = {
  all:"\u5168\u90e8\u533a\u57df", region:"\u533a\u57df", customer:"\u5ba2\u6237\u540d\u79f0", company:"\u516c\u53f8\u5e94\u6536", customerBook:"\u5ba2\u6237\u8d26\u9762\u91d1\u989d", difference:"\u5bf9\u8d26\u5dee\u989d", transit:"\u5728\u9014\u91d1\u989d", returned:"\u9000\u7968\u91d1\u989d", lost:"\u4e22\u7968\u91d1\u989d", instrument:"\u4eea\u5668\u8bbe\u5907", other:"\u5176\u4ed6\u539f\u56e0", note:"\u5dee\u989d\u539f\u56e0\u5907\u6ce8", badDebt:"\u6b7b\u8d26\u91d1\u989d", adjustment:"\u8c03\u8d26\u91d1\u989d", cleared:"26\u5e742\u5b63\u5ea6\u662f\u5426\u5bf9\u6e05", clear:"\u5bf9\u6e05", uncleared:"\u672a\u5bf9\u6e05", unreconciled:"\u672a\u5bf9\u8d26",
  local:"\u672c\u673a\u7248", import:"\u4e0a\u4f20\u5bf9\u8d26\u5b63\u5ea6\u8868", uploadLedger:"\u4e0a\u4f20\uff0f\u66ff\u6362\u672c\u5e74\u5f80\u6765\u660e\u7ec6", uploadMaterials:"\u5bfc\u5165\u8d44\u6599\u63d0\u4f9b\u60c5\u51b5\u8868", clearData:"\u6e05\u9664\u672c\u673a\u6570\u636e", importTitle:"\u5b63\u5ea6\u5bf9\u8d26", importHint:"\u5386\u53f2\u5f80\u6765\u660e\u7ec6\u5df2\u7ecf\u4fdd\u7559\uff1b\u6bcf\u5b63\u5ea6\u4e0a\u4f20\u672c\u5e74\u6700\u65b0\u5f80\u6765\u660e\u7ec6\uff0c\u6838\u9a8c\u65f6\u4f1a\u4e00\u8d77\u67e5\u627e\u3002", needImport:"\u8bf7\u5148\u4e0a\u4f20\u5bf9\u8d26\u5b63\u5ea6\u8868", sales:"\u9500\u552e\u586b\u5199", fill:"\u586b\u5199", customerFallback:"\u5ba2\u6237", detail:"\u5bf9\u8d26\u660e\u7ec6", invoiceDate:"\u5f00\u7968\u65e5\u671f", invoice:"\u53d1\u7968\u53f7", amount:"\u91d1\u989d", reason:"\u5dee\u989d\u8bf4\u660e", transitReview:"\u5728\u9014\u91d1\u989d\uff08\u9700\u590d\u6838\uff09", returnReview:"\u9000\u7968\u91d1\u989d\uff08\u9700\u590d\u6838\uff09", lostReview:"\u4e22\u7968\u91d1\u989d\uff08\u9700\u590d\u6838\uff09", instrumentReview:"\u4eea\u5668\u8bbe\u5907\uff08\u9700\u590d\u6838\uff09", otherInvoice:"\u5176\u4ed6\uff08\u6709\u53d1\u7968\uff09", otherNoInvoice:"\u5176\u4ed6\uff08\u65e0\u53d1\u7968\u53ca\u65e0\u6cd5\u9a8c\u8bc1\uff09", add:"\uff0b \u65b0\u589e\u4e00\u7b14", remove:"\u5220\u9664\u672c\u7b14", total:"\u516d\u7c7b\u5dee\u989d\u5408\u8ba1\uff1a", compare:"\u4e0e\u5bf9\u8d26\u5dee\u989d\uff1a", same:"\u4e00\u81f4", different:"\u4e0d\u4e00\u81f4", save:"\u4fdd\u5b58\u672c\u6b21\u586b\u5199", loading:"\u6b63\u5728\u52a0\u8f7d\u5f80\u6765\u660e\u7ec6\u2026", matched:"\u5f80\u6765\u660e\u7ec6\u6838\u9a8c\uff1a\u6b63\u786e", missing:"\u5f80\u6765\u660e\u7ec6\u672a\u627e\u5230\u6b64\u53d1\u7968", incomplete:"\u8bf7\u5b8c\u6574\u586b\u5199\u65e5\u671f\u3001\u53d1\u7968\u53f7\u548c\u91d1\u989d", saved:"\u5df2\u4fdd\u5b58\u9500\u552e\u586b\u5199\u5185\u5bb9\u3002"
};
const STORAGE_KEY = "local-quarterly-reconciliation";
const MATERIAL_HEADERS = ["\u5bf9\u8d26\u51fd", "\u5bf9\u8d26\u786e\u8ba4\u51fd", "SPD\u786e\u8ba4\u51fd", "SPD\u5e93\u5b58\u786e\u8ba4\u51fd", "\u5728\u9014\u8bc1\u660e", "\u7cbe\u51c6\u6838\u9500", "\u50ac\u6b3e\u51fd\u9001\u8fbe\u8bc1\u660e"];
const RESPONSIBLE_HEADER = "\u5bf9\u8d26\u8d1f\u8d23\u4eba";
let historicalLedgerKeys: Set<string> | null = null;
let historicalLedgerLookup: LedgerLookup = {};
const blankInvoice = (): InvoiceEntry => ({ date:"", invoice:"", amount:"", note:"" });
const blankOther = (): OtherEntry => ({ amount:"", note:"", image:"" });
const empty = (): DetailForm => ({ customerAmount:"", responsible:"", transit:[blankInvoice()], returned:[blankInvoice()], lost:[blankInvoice()], instrument:[blankInvoice()], otherInvoice:[blankInvoice()], other:[blankOther()], badDebt:"", badDebtReason:"", adjustment:"", adjustmentReason:"", resolutionSolution:"", resolutionTime:"" });
const num = (value: unknown) => { const n = Number(String(value ?? "").replace(/,/g, "")); return Number.isFinite(n) ? n : 0; };
const hasValue = (value: unknown) => String(value ?? "").trim() !== "";
const money = (value: number) => value.toLocaleString("zh-CN", { minimumFractionDigits:2, maximumFractionDigits:2 });
const tableColumnClass = (header: unknown) => { const name=String(header); if(name.includes("账期")) return "account-period-cell"; if(name===T.customer||name.includes("客户名称")) return "customer-name-cell"; if(/差额(原因|明细|说明)/.test(name)) return "detail-note-cell"; return ""; };
const tableColumnHeadingClass = (header: unknown) => tableColumnClass(header)==="detail-note-cell" ? "detail-note-heading" : tableColumnClass(header)==="customer-name-cell" ? "customer-name-heading" : tableColumnClass(header)==="account-period-cell" ? "account-period-heading" : "";
const tableHeader = (header: unknown) => String(header);
const tableValue = (header: unknown, value: unknown) => { const text=String(value??""); const name=String(header); if(!text||![T.difference,T.company,T.customerBook,T.transit,T.returned,T.lost,T.instrument,T.other].includes(name)) return text; const amount=Number(text.replace(/,/g,"")); return Number.isFinite(amount)?amount.toLocaleString("zh-CN",{maximumFractionDigits:2}):text; };
const displayTableValue = (header: unknown, value: unknown, customerAmount: unknown) => String(header)===T.difference&&!hasValue(customerAmount) ? "—" : tableValue(header,value)||"—";
const isMoneyHeader = (header: unknown) => [T.company,T.customerBook,T.difference,T.transit,T.returned,T.lost,T.instrument,T.other,T.badDebt,T.adjustment].includes(String(header));
const cellClass = (header: unknown, index:number) => [tableColumnClass(header),isMoneyHeader(header)?"money-cell":"",[T.company,T.customerBook].includes(String(header))?"primary-money":"",String(header)===T.difference?"difference-cell":"",String(header).includes("是否对清")?"status-cell":"",index===0?"sticky-index":"",String(header).includes("账套")?"sticky-account":"",String(header)===T.customer?"sticky-customer":""].filter(Boolean).join(" ");
const clearedBadgeClass = (value: unknown) => { const text=String(value??""); return text===T.clear ? "is-cleared" : text===T.unreconciled ? "is-unreconciled" : text===T.uncleared ? "is-uncleared" : "is-empty"; };
const reorderReviewColumns = (source: LocalSheet) => { const review=[T.lost,T.instrument].filter(header=>source.headers.includes(header)); const returnedAt=source.headers.indexOf(T.returned); if(!review.length||returnedAt<0)return source; const base=source.headers.filter(header=>!review.includes(header)); const insertAt=base.indexOf(T.returned)+1; const headers=[...base.slice(0,insertAt),...review,...base.slice(insertAt)]; if(headers.every((header,index)=>header===source.headers[index]))return source; const positions=headers.map(header=>source.headers.indexOf(header)); return {...source,headers,rows:source.rows.map(row=>positions.map(position=>row[position]??""))}; };
const placeMaterialHeaders = (source: LocalSheet) => { const materialHeaders=MATERIAL_HEADERS.filter(header=>source.headers.includes(header)); const base=source.headers.filter(header=>!MATERIAL_HEADERS.includes(header)); const solutionAt=base.indexOf("\u89e3\u51b3\u65b9\u6848"); if(!materialHeaders.length||solutionAt<0)return source; const headers=[...base.slice(0,solutionAt),...materialHeaders,...base.slice(solutionAt)]; if(headers.every((header,index)=>header===source.headers[index]))return source; const positions=headers.map(header=>source.headers.indexOf(header)); return {...source,headers,rows:source.rows.map(row=>positions.map(position=>position<0?"":row[position]??""))}; };
const ensureMaterialHeaders = (source: LocalSheet) => placeMaterialHeaders({...source,headers:[...source.headers,...MATERIAL_HEADERS.filter(header=>!source.headers.includes(header))],rows:source.rows.map(row=>[...row])});
const sum = (entries: Array<{ amount:string }>) => entries.reduce((total, entry) => total + num(entry.amount), 0);
const currentQuarterRange = (source: LocalSheet) => {
  const reference=[...source.headers,source.fileName].join(" ");
  const match=reference.match(/(\d{2,4})\s*\u5e74\s*([1-4])\s*\u5b63\u5ea6/);
  if(!match) return null;
  const year=Number(match[1].length===2 ? "20"+match[1] : match[1]);
  const quarter=Number(match[2]);
  const months: Record<number,[number,number]>={1:[1,3],2:[4,6],3:[7,9],4:[10,12]};
  return {year,months:months[quarter]};
};
const isCurrentQuarterInvoice = (date:string, range:{year:number;months:[number,number]}|null) => {
  const digits=date.replace(/[^0-9]/g,"");
  if(!range||digits.length<6) return false;
  const year=Number(digits.slice(0,4)), month=Number(digits.slice(4,6));
  return year===range.year&&month>=range.months[0]&&month<=range.months[1];
};
const needsDifferenceStripe = (source:LocalSheet, id:number, difference:number) => {
  if(Math.abs(difference)<.01) return false;
  const detail=source.details?.[String(id)], range=currentQuarterRange(source);
  if(!detail||!range) return true;
  const invoiceEntries=[...detail.transit,...detail.returned,...(detail.lost??[]),...(detail.instrument??[]),...detail.otherInvoice]
    .filter(entry=>num(entry.amount)!==0||entry.invoice.trim()!==""||entry.date.trim()!=="");
  const hasNoInvoiceAmount=sum(detail.other)!==0;
  if(hasNoInvoiceAmount||!invoiceEntries.length) return true;
  return invoiceEntries.some(entry=>!entry.invoice.trim()||!isCurrentQuarterInvoice(entry.date,range));
};
const backfillClearedStatus = (source: LocalSheet) => { const clearedAt=source.headers.findIndex(header=>String(header).replace(/\s/g,"").includes("是否对清")); const companyAt=source.headers.indexOf(T.company),customerAt=source.headers.indexOf(T.customerBook); if(clearedAt<0||companyAt<0||customerAt<0)return source; let changed=false; const rows=source.rows.map((sourceRow,id)=>{const detail=source.details?.[String(id)]; const customerValue=detail?.customerAmount??sourceRow[customerAt]; const filled=String(customerValue??"").trim()!==""; const row=[...sourceRow]; const difference=num(row[companyAt])-num(customerValue); const total=detail?sum(detail.transit)+sum(detail.returned)+sum(detail.lost??[])+sum(detail.instrument??[])+sum(detail.otherInvoice)+sum(detail.other):0; const status=!filled?T.unreconciled:(Math.abs(difference)<.01||Math.abs(difference-total)<.01)?T.clear:T.uncleared; if(row[clearedAt]!==status){row[clearedAt]=status;changed=true;} return row;});
 return changed?{...source,rows}:source; };
const anyInvoice = (entry: InvoiceEntry) => Boolean(entry.date || entry.invoice || entry.amount || entry.note);
const ledgerKey = (entry: InvoiceEntry) => `${entry.invoice.trim()}|${entry.date.replace(/[^0-9]/g, "").slice(0,8)}|${num(entry.amount).toFixed(2)}`;
const validLedgerEntry = (entry: InvoiceEntry, keys: Set<string> | null, lookup:LedgerLookup = historicalLedgerLookup) => { if(!anyInvoice(entry))return true; if(!entry.date||!entry.invoice||entry.amount==="")return false; const matched=lookup[entry.invoice.trim()]; return Boolean((matched&&matched.dates.includes(entry.date)&&Math.abs(matched.amount-num(entry.amount))<.01)||keys?.has(ledgerKey(entry))); };
const findLedgerMatch = (invoice:string, lookup:LedgerLookup, keys:Set<string>|null) => { const number=invoice.trim(); if(lookup[number])return lookup[number]; if(number.length<7||!keys)return null; const dates=new Set<string>(); let amount=0,found=false; for(const key of keys){if(!key.startsWith(`${number}|`))continue;const [,date,value]=key.split("|");if(date.length!==8)continue;dates.add(`${date.slice(0,4)}-${date.slice(4,6)}-${date.slice(6,8)}`);amount+=Number(value);found=true;} return found?{amount,dates:[...dates].sort()}:null; };
const normalizeDate = (value: unknown) => { const text = String(value ?? "").trim(); const digits = text.replace(/[^0-9]/g, ""); if (digits.length === 8) return digits; const date = new Date(text); if (!Number.isNaN(date.getTime())) return `${date.getFullYear()}${String(date.getMonth()+1).padStart(2,"0")}${String(date.getDate()).padStart(2,"0")}`; return ""; };
const headerIndex = (headers: unknown[], names: string[]) => headers.findIndex(header => { const text=String(header??"").replace(/\s/g,""); return names.some(name=>text.includes(name)); });
const dbRequest = <T,>(mode: IDBTransactionMode, action: (store: IDBObjectStore) => IDBRequest<T>) => new Promise<T>((resolve,reject) => { const open=indexedDB.open("quarterly-reconciliation",1); open.onupgradeneeded=()=>open.result.createObjectStore("ledger"); open.onerror=()=>reject(open.error); open.onsuccess=()=>{ const tx=open.result.transaction("ledger",mode); const request=action(tx.objectStore("ledger")); request.onsuccess=()=>resolve(request.result); request.onerror=()=>reject(request.error); }; });
const loadCurrentLedger = () => dbRequest<LedgerUpload | undefined>("readonly", store => store.get("current"));
const saveCurrentLedger = (value: LedgerUpload) => dbRequest<IDBValidKey>("readwrite", store => store.put(value,"current"));
async function readLedgerFiles(files: File[]) { const keys=new Set<string>(); for(const file of files) { const workbook=XLSX.read(await file.arrayBuffer(),{type:"array",cellDates:true}); for(const sheetName of workbook.SheetNames) { const rows=XLSX.utils.sheet_to_json<unknown[]>(workbook.Sheets[sheetName],{header:1,defval:"",raw:false,dateNF:"yyyy-mm-dd"}); const headerRow=rows.slice(0,5).find(row=>headerIndex(row,["\u53d1\u7968\u53f7","\u53d1\u7968\u4ee3\u7801","\u5355\u636e\u7f16\u53f7","\u6458\u8981"])>=0); if(!headerRow) continue; const invoiceAt=headerIndex(headerRow,["\u53d1\u7968\u53f7","\u53d1\u7968\u4ee3\u7801","\u5355\u636e\u7f16\u53f7","\u6458\u8981"]); const dateAt=headerIndex(headerRow,["\u5f00\u7968\u65e5\u671f","\u4e1a\u52a1\u65e5\u671f","\u8d22\u52a1\u65e5\u671f","\u4ea4\u6613\u65e5\u671f","\u65e5\u671f"]); const amountAt=headerIndex(headerRow,["\u672c\u671f\u5e94\u6536","\u5e94\u6536\u91d1\u989d","\u5f00\u7968\u91d1\u989d","\u542b\u7a0e\u91d1\u989d","\u501f\u65b9","\u91d1\u989d"]); if(invoiceAt<0||dateAt<0||amountAt<0) continue; const start=rows.indexOf(headerRow)+1; for(const row of rows.slice(start)) { const source=row.map(value=>String(value??"")).join(" "); const cell=String(row[invoiceAt]??"").replace(/\s/g,""); const matched=source.match(/(?<!\d)(?:\d{8}|\d{20})(?!\d)/); const invoice=(matched?.[0]??cell).replace(/\s/g,""); const date=normalizeDate(row[dateAt]); const amount=num(row[amountAt]); if(invoice&&date&&amount) keys.add(`${invoice}|${date}|${amount.toFixed(2)}`); } } } return [...keys]; }

export function QuarterlyReconciliation({ mode="table" }: { mode?: "table" | "import" }) {
  const [sheet, setSheet] = useState<LocalSheet | null>(null);
  const [region, setRegion] = useState(T.all);
  const [message, setMessage] = useState("");
  const [active, setActive] = useState<number | null>(null);
  const [form, setForm] = useState<DetailForm>(empty());
  const [ledgerKeys, setLedgerKeys] = useState<Set<string> | null>(null);
  const [currentLedgerKeys, setCurrentLedgerKeys] = useState<Set<string>>(new Set());
  const [currentLedgerInfo, setCurrentLedgerInfo] = useState<LedgerUpload | null>(null);
  const [uploadingLedger, setUploadingLedger] = useState(false);
  const [ledgerError, setLedgerError] = useState(false);
  const [ledgerLookup, setLedgerLookup] = useState<LedgerLookup>({});
  const [previewImage, setPreviewImage] = useState<string | null>(null);
  const [columnFilters, setColumnFilters] = useState<Record<number,string>>({});
  const [hiddenColumns, setHiddenColumns] = useState<number[]>([]);
  const [salesHidden, setSalesHidden] = useState(false);
  const [filterColumns, setFilterColumns] = useState<number[]>([]);
  const [filterColumn, rawSetFilterColumn] = useState<number | null>(null);
  const [searchInput, setSearchInput] = useState("");
  const [searchQuery, setSearchQuery] = useState("");
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(10);
  const [columnMenuOpen, setColumnMenuOpen] = useState(false);
  const [stripeFilter, setStripeFilter] = useState<"all"|"review">("all");
  const [columnWidths, setColumnWidths] = useState<Record<number,number>>({});
  const setFilterColumn = (column:number | null) => { rawSetFilterColumn(null); if(column!==null) setFilterColumns(columns=>columns.includes(column) ? columns.filter(item=>item!==column) : [...columns,column]); };

  useEffect(() => { try { const saved = localStorage.getItem(STORAGE_KEY); if (saved) { const next=ensureMaterialHeaders(reorderReviewColumns(backfillClearedStatus(JSON.parse(saved)))); setSheet(next); localStorage.setItem(STORAGE_KEY,JSON.stringify(next)); } } catch { localStorage.removeItem(STORAGE_KEY); } }, []);
  useEffect(() => { let alive = true; fetch("/ledger_keys.json").then(r => { if (!r.ok) throw new Error("ledger"); return r.json() as Promise<string[]>; }).then(async keys => { const lookup=await fetch("/ledger_invoice_lookup.json").then(r=>r.ok?r.json() as Promise<LedgerLookup>:{}).catch(()=>({})); const saved=await loadCurrentLedger().catch(()=>undefined); historicalLedgerKeys=new Set(keys); historicalLedgerLookup=lookup; if (alive) { setLedgerKeys(new Set([...keys,...(saved?.keys??[])])); setLedgerLookup(lookup); } }).catch(() => { if (alive) setLedgerError(true); }); return () => { alive = false; }; }, []);
  useEffect(() => { loadCurrentLedger().then(saved => { if(saved) { setCurrentLedgerInfo(saved); setCurrentLedgerKeys(new Set(saved.keys)); } }).catch(() => undefined); }, []);
  useEffect(() => { const timer=window.setTimeout(()=>setSearchQuery(searchInput.trim()),250); return ()=>window.clearTimeout(timer); }, [searchInput]);

  const index = (name:string) => sheet?.headers.indexOf(name) ?? -1;
  const clearedIndex = sheet?.headers.findIndex(header => String(header).replace(/\s/g, "").includes("是否对清")) ?? -1;
  const regionIndex = index(T.region); const customerIndex = index(T.customer); const companyIndex = index(T.company); const customerBookIndex = index(T.customerBook); const accountIndex = sheet?.headers.findIndex(header=>String(header).replace(/\s/g,"").includes("\u8d26\u5957")) ?? -1; const responsibleIndex = sheet?.headers.findIndex(header=>String(header).replace(/\s/g,"").includes(RESPONSIBLE_HEADER)) ?? -1;
  const columnStyle = (column:number) => { const width=columnWidths[column]; const style:Record<string,string|number>={}; if(width) { style.width=width; style.minWidth=width; } if(column===0) style.left=0; if(column===accountIndex) style.left=columnWidths[0]??64; if(column===customerIndex) style.left=(columnWidths[0]??64)+(columnWidths[accountIndex]??110); return Object.keys(style).length?style:undefined; };
  const startColumnResize = (event:ReactPointerEvent<HTMLButtonElement>, column:number) => { event.preventDefault(); event.stopPropagation(); const header=event.currentTarget.closest("th"); const startWidth=header?.getBoundingClientRect().width??100; const startX=event.clientX; const resize=(moveEvent:PointerEvent) => setColumnWidths(widths=>({...widths,[column]:Math.max(72,Math.round(startWidth+moveEvent.clientX-startX))})); const stop=() => { window.removeEventListener("pointermove",resize); window.removeEventListener("pointerup",stop); document.body.style.cursor=""; document.body.style.userSelect=""; }; document.body.style.cursor="col-resize"; document.body.style.userSelect="none"; window.addEventListener("pointermove",resize); window.addEventListener("pointerup",stop); };
  const regions = useMemo(() => sheet ? Array.from(new Set(sheet.rows.map(row => String(row[regionIndex] ?? "\u672a\u586b\u5199")))) : [], [sheet, regionIndex]);
  const shown = useMemo(() => sheet ? sheet.rows.map((row,id) => ({row,id})).filter(({row,id}) => { const needle=searchQuery.toLocaleLowerCase(); const searchable=[row[customerIndex],row[responsibleIndex],row[regionIndex]].map(value=>String(value??"").toLocaleLowerCase()).join(" "); return (region === T.all || String(row[regionIndex] ?? "\u672a\u586b\u5199") === region) && (!needle||searchable.includes(needle)) && Object.entries(columnFilters).every(([column,value])=>!value||String(row[Number(column)]??"").includes(value)) && (stripeFilter==="all"||needsDifferenceStripe(sheet,id,num(row[index(T.difference)]))); }) : [], [sheet, region, regionIndex, customerIndex, responsibleIndex, searchQuery, columnFilters, stripeFilter]);
  const pageCount=Math.max(1,Math.ceil(shown.length/pageSize));
  const pagedRows=shown.slice((page-1)*pageSize,page*pageSize);
  useEffect(()=>{setPage(1);},[region,searchQuery,columnFilters,stripeFilter,pageSize]);
  useEffect(()=>{if(page>pageCount)setPage(pageCount);},[page,pageCount]);
  const matchingLedgerKeys = useMemo(() => ledgerKeys ? new Set([...ledgerKeys, ...currentLedgerKeys]) : null, [ledgerKeys, currentLedgerKeys]);
  const saveSheet = (next:LocalSheet) => { const headers=[...next.headers]; const solution="\u89e3\u51b3\u65b9\u6848", time="\u89e3\u51b3\u65f6\u95f4"; if(!headers.includes(T.lost)) headers.push(T.lost); if(!headers.includes(T.instrument)) headers.push(T.instrument); if(!headers.includes(solution)) headers.push(solution); if(!headers.includes(time)) headers.push(time); MATERIAL_HEADERS.forEach(header=>{if(!headers.includes(header))headers.push(header);}); const ordered=placeMaterialHeaders(reorderReviewColumns({...next,headers,rows:next.rows.map(row=>[...row])})); const rows=ordered.rows.map(row=>[...row]); Object.entries(ordered.details??{}).forEach(([id,detail])=>{const row=rows[Number(id)]; if(row){row[ordered.headers.indexOf(T.lost)]=sum(detail.lost??[]);row[ordered.headers.indexOf(T.instrument)]=sum(detail.instrument??[]);row[ordered.headers.indexOf(solution)]=detail.resolutionSolution;row[ordered.headers.indexOf(time)]=detail.resolutionTime;}}); const saved={...ordered,rows}; setSheet(saved); localStorage.setItem(STORAGE_KEY, JSON.stringify(saved)); window.dispatchEvent(new Event("reconciliation-updated")); };
  const setCell = (row:unknown[], name:string, value:string|number) => { const i=index(name); if(i>=0) row[i]=value; };
  const updateResponsible = (value:string) => { const nextForm={...form,responsible:value}; setForm(nextForm); if(!sheet||active===null||responsibleIndex<0)return; const rows=sheet.rows.map(row=>[...row]); rows[active][responsibleIndex]=value; saveSheet({...sheet,rows,details:{...(sheet.details??{}),[String(active)]:nextForm}}); };
  const hideColumn = (column:number) => { setHiddenColumns(columns=>columns.includes(column)?columns:[...columns,column]); setFilterColumns(columns=>columns.filter(item=>item!==column)); };
  const toggleFilterColumn = (column:number) => setFilterColumns(columns=>columns.includes(column) ? columns.filter(item=>item!==column) : [...columns,column]);
  const exportTable = () => { if(!sheet) return; const columns=sheet.headers.map((header,index)=>({header,index})).filter(({index})=>!hiddenColumns.includes(index)); const workbook=XLSX.utils.book_new(); const worksheet=XLSX.utils.aoa_to_sheet([columns.map(column=>column.header),...shown.map(({row})=>columns.map(({header,index})=>displayTableValue(header,row[index],row[customerBookIndex])))]); XLSX.utils.book_append_sheet(workbook,worksheet,"本年度对账明细"); XLSX.writeFile(workbook,`${sheet.fileName.replace(/\.(xlsx|xls)$/i,"")}-导出.xlsx`); };
  const refreshTable = () => { try { const saved=localStorage.getItem(STORAGE_KEY); if(saved) setSheet(reorderReviewColumns(backfillClearedStatus(JSON.parse(saved)))); } catch { /* Keep the currently visible sheet if the saved copy is unavailable. */ } setRegion(T.all); setStripeFilter("all"); setColumnFilters({}); setFilterColumns([]); setHiddenColumns([]); setSalesHidden(false); setMessage("已刷新表格，并恢复全部明细。"); };

  async function importFile(event:ChangeEvent<HTMLInputElement>) { const file=event.target.files?.[0]; if(!file) return; try { const wb=XLSX.read(await file.arrayBuffer(),{type:"array"}); const all=XLSX.utils.sheet_to_json<unknown[]>(wb.Sheets[wb.SheetNames[0]],{header:1,defval:""}); const headers=(all[0]??[]).map(String); const rows=all.slice(1).filter(row=>row.some(value=>value!=="")); if(!headers.length||!rows.length) throw new Error("\u6ca1\u6709\u8bfb\u53d6\u5230\u53ef\u7528\u7684\u8868\u5934\u6216\u6570\u636e\u3002"); saveSheet({headers,rows,fileName:file.name,details:{}}); setRegion(T.all); setMessage(`\u5df2\u5bfc\u5165 ${rows.length} \u6761\u8bb0\u5f55\u3002`); } catch(error) { setMessage(error instanceof Error ? error.message : "\u5bfc\u5165\u5931\u8d25\u3002"); } event.target.value=""; }
  async function importMaterials(event:ChangeEvent<HTMLInputElement>) { const file=event.target.files?.[0]; if(!file) return; if(!sheet){setMessage("\u8bf7\u5148\u4e0a\u4f20\u5bf9\u8d26\u5b63\u5ea6\u8868\uff0c\u518d\u5bfc\u5165\u8d44\u6599\u63d0\u4f9b\u60c5\u51b5\u8868\u3002"); event.target.value=""; return;} try { const workbook=XLSX.read(await file.arrayBuffer(),{type:"array"}); const all=XLSX.utils.sheet_to_json<unknown[]>(workbook.Sheets[workbook.SheetNames[0]],{header:1,defval:""}); const sourceHeaders=(all[0]??[]).map(String); const sourceRows=all.slice(1).filter(row=>row.some(value=>String(value??"").trim()!=="")); const sourceAccount=headerIndex(sourceHeaders,["\u8d26\u5957"]), sourceRegion=headerIndex(sourceHeaders,[T.region]), sourceCustomer=headerIndex(sourceHeaders,[T.customer]); if(sourceAccount<0||sourceRegion<0||sourceCustomer<0) throw new Error("\u8d44\u6599\u63d0\u4f9b\u60c5\u51b5\u8868\u5fc5\u987b\u5305\u542b\u8d26\u5957\u3001\u533a\u57df\u3001\u5ba2\u6237\u540d\u79f0\u5217\u3002"); const headers=[...sheet.headers]; MATERIAL_HEADERS.forEach(header=>{if(!headers.includes(header))headers.push(header);}); const prepared=placeMaterialHeaders({...sheet,headers,rows:sheet.rows.map(row=>[...row])}); const accountAt=headerIndex(prepared.headers,["\u8d26\u5957"]), targetRegion=headerIndex(prepared.headers,[T.region]), targetCustomer=headerIndex(prepared.headers,[T.customer]); if(accountAt<0||targetRegion<0||targetCustomer<0) throw new Error("\u672c\u5e74\u5ea6\u5bf9\u8d26\u8868\u5fc5\u987b\u5305\u542b\u8d26\u5957\u3001\u533a\u57df\u3001\u5ba2\u6237\u540d\u79f0\u5217\u3002"); const key=(account:unknown,area:unknown,customer:unknown)=>[account,area,customer].map(value=>String(value??"").replace(/\s/g,"").trim()).join("|"); const sourceByKey=new Map<string,unknown[]>(); sourceRows.forEach(row=>{const matchKey=key(row[sourceAccount],row[sourceRegion],row[sourceCustomer]); if(matchKey!=="||")sourceByKey.set(matchKey,row);}); const sourceMaterials=MATERIAL_HEADERS.map(header=>headerIndex(sourceHeaders,[header])); const targetMaterials=MATERIAL_HEADERS.map(header=>prepared.headers.indexOf(header)); let matched=0; const rows=prepared.rows.map(row=>{const source=sourceByKey.get(key(row[accountAt],row[targetRegion],row[targetCustomer])); if(!source)return row; matched+=1; const next=[...row]; sourceMaterials.forEach((sourceAt,index)=>{if(sourceAt>=0&&String(source[sourceAt]??"").trim()!=="")next[targetMaterials[index]]=source[sourceAt];}); return next;}); saveSheet({...prepared,rows}); setMessage("\u5df2\u5bfc\u5165\u8d44\u6599\u63d0\u4f9b\u60c5\u51b5\u8868\uff1a\u5339\u914d "+matched+" \u6761\u5ba2\u6237\u8bb0\u5f55\u3002"); } catch(error) { setMessage(error instanceof Error ? error.message : "\u8d44\u6599\u63d0\u4f9b\u60c5\u51b5\u8868\u5bfc\u5165\u5931\u8d25\u3002"); } event.target.value=""; }
  async function importCurrentLedger(event:ChangeEvent<HTMLInputElement>) { const files=Array.from(event.target.files??[]); if(!files.length) return; setUploadingLedger(true); try { const keys=await readLedgerFiles(files); if(!keys.length) throw new Error("\u6ca1\u6709\u4ece\u6587\u4ef6\u4e2d\u8bfb\u53d6\u5230\u53ef\u6838\u9a8c\u7684\u53d1\u7968\u53f7\u3001\u65e5\u671f\u548c\u91d1\u989d\u3002"); const upload={keys,fileNames:files.map(file=>file.name),updatedAt:new Date().toLocaleString("zh-CN")}; await saveCurrentLedger(upload); setCurrentLedgerKeys(new Set(keys)); setLedgerKeys(historicalLedgerKeys ? new Set([...historicalLedgerKeys,...keys]) : null); setCurrentLedgerInfo(upload); setMessage(`\u5df2\u66ff\u6362\u672c\u5e74\u5f80\u6765\u660e\u7ec6\uff1a${keys.length} \u6761\u53ef\u6838\u9a8c\u8bb0\u5f55\u3002`); } catch(error) { setMessage(error instanceof Error ? error.message : "\u5f80\u6765\u660e\u7ec6\u4e0a\u4f20\u5931\u8d25\u3002"); } finally { setUploadingLedger(false); event.target.value=""; } }
  function clearData() { localStorage.removeItem(STORAGE_KEY); setSheet(null); setRegion(T.all); setMessage("\u5df2\u6e05\u9664\u672c\u673a\u4fdd\u5b58\u7684\u6570\u636e\u3002"); }
  function open(id:number) { if(!sheet) return; const row=sheet.rows[id]; const old=sheet.details?.[String(id)]; const value=(name:string)=>String(row[index(name)]??""); setForm(old ? {...empty(),...old,responsible:old.responsible??String(row[responsibleIndex]??""),lost:old.lost??[blankInvoice()],instrument:old.instrument??[blankInvoice()]} : {...empty(),customerAmount:value(T.customerBook),responsible:String(row[responsibleIndex]??""),transit:[{...blankInvoice(),amount:value(T.transit)}],returned:[{...blankInvoice(),amount:value(T.returned)}],lost:[{...blankInvoice(),amount:value(T.lost)}],instrument:[{...blankInvoice(),amount:value(T.instrument)}],badDebt:value(T.badDebt),adjustment:value(T.adjustment)}); setActive(id); }
  function commit() { if(!sheet || active===null) return; const needsCheck=[...form.transit,...form.returned,...form.lost,...form.instrument].filter(anyInvoice); if(ledgerError) { window.alert("往来明细核验数据加载失败，请刷新后重试。"); return; } if(!matchingLedgerKeys) { window.alert("正在加载往来明细，请稍候再保存。"); return; } if(needsCheck.some(entry=>!validLedgerEntry(entry,matchingLedgerKeys))) { window.alert("在途、退票、丢票或仪器设备中存在未匹配的发票，不能保存。"); return; } const company=num(sheet.rows[active][companyIndex]); const customer=num(form.customerAmount); const difference=company-customer; const transit=sum(form.transit); const returned=sum(form.returned); const lost=sum(form.lost); const instrument=sum(form.instrument); const otherInvoice=sum(form.otherInvoice); const other=sum(form.other); const total=transit+returned+lost+instrument+otherInvoice+other; const rows=sheet.rows.map(row=>[...row]); const row=rows[active]; setCell(row,T.customerBook,form.customerAmount===""?"":customer); setCell(row,T.difference,form.customerAmount===""?"":difference); setCell(row,T.transit,transit); setCell(row,T.returned,returned); setCell(row,T.lost,lost); setCell(row,T.instrument,instrument); setCell(row,T.other,otherInvoice+other); setCell(row,T.badDebt,form.badDebt); setCell(row,T.adjustment,form.adjustment); const notes=[...form.transit.map(e=>e.note&&`在途：${e.note}`),...form.returned.map(e=>e.note&&`退票：${e.note}`),...form.lost.map(e=>e.note&&`丢票：${e.note}`),...form.instrument.map(e=>e.note&&`仪器设备：${e.note}`),...form.otherInvoice.map(e=>e.note&&`其他（有发票）：${e.note}`),...form.other.map(e=>e.note&&`其他：${e.note}`)].filter(Boolean).join("；"); setCell(row,T.note,notes); if(clearedIndex>=0) row[clearedIndex]=form.customerAmount===""?T.unreconciled:(Math.abs(difference)<.01 || Math.abs(difference-total)<.01) ? T.clear:T.uncleared; saveSheet({...sheet,rows,details:{...(sheet.details??{}),[String(active)]:form}}); setMessage(T.saved); setActive(null); }

  const company=active!==null&&sheet?num(sheet.rows[active][companyIndex]):0; const difference=company-num(form.customerAmount); const total=sum(form.transit)+sum(form.returned)+sum(form.lost)+sum(form.instrument)+sum(form.otherInvoice)+sum(form.other); const isClear=form.customerAmount!==""&&(Math.abs(difference)<.01 || Math.abs(difference-total)<.01);

  return (
    <>
      <section className={`local-tool ${mode === "import" ? "data-import-tool" : "detail-table-tool"}`}>
        <div className="local-toolbar">
          <div><p className="eyebrow">{mode === "import" ? "数据导入" : T.local}</p><h2>{mode === "import" ? "数据导入" : "本年度对账详细情况"}</h2><p>{mode === "import" ? T.importHint : "查看、筛选、填写和导出本年度对账明细。"}</p></div>
          {mode === "import" ? <div className="toolbar-actions upload-actions">
            <label className="file-button">{T.import}<input type="file" accept=".xlsx,.xls" onChange={importFile}/></label>
            <label className="file-button ledger-upload">{uploadingLedger ? T.loading : T.uploadLedger}<input type="file" accept=".xlsx,.xls" multiple disabled={uploadingLedger} onChange={importCurrentLedger}/></label>
            <label className="file-button materials-upload">{T.uploadMaterials}<input type="file" accept=".xlsx,.xls" onChange={importMaterials}/></label>
            {sheet && <button className="clear-button" onClick={clearData}>{T.clearData}</button>}
          </div> : <div className="toolbar-actions"><button className="refresh-button" type="button" onClick={refreshTable}>刷新</button><button className="export-button" type="button" onClick={exportTable} disabled={!sheet}>导出</button></div>}
        </div>
        {currentLedgerInfo && <p className="ledger-info">{`\u672c\u5e74\u5f80\u6765\u660e\u7ec6\uff1a${currentLedgerInfo.fileNames.join("、")} \uff08${currentLedgerInfo.keys.length}\u6761\uff0c${currentLedgerInfo.updatedAt}\uff09`}</p>}
        {message && <p className="import-message">{message}</p>}
        {mode !== "import" && sheet && filterColumns.length>0 && <div className="column-filter multi-column-filter">{filterColumns.map(column=><div className="filter-item" key={column}><b>筛选“{sheet.headers[column]}”</b><input value={columnFilters[column]??""} placeholder="输入筛选内容" onChange={event=>setColumnFilters(filters=>({...filters,[column]:event.target.value}))}/><button type="button" onClick={()=>setColumnFilters(filters=>({...filters,[column]:""}))}>清除</button><button type="button" onClick={()=>setFilterColumns(columns=>columns.filter(item=>item!==column))}>关闭</button></div>)}</div>}
        {mode === "import" ? <div className="import-status"><strong>{sheet ? "本年度对账表已导入" : T.needImport}</strong><span>{sheet ? `${sheet.fileName}，共 ${sheet.rows.length} 条记录。数据已保存在本机，可返回“本年度对账详细情况”继续填写。` : "请先上传对账季度表，再按需要上传或替换本年往来明细。"}</span></div> : !sheet ? <div className="local-empty"><strong>{T.needImport}</strong></div> : <>
          <div className="reconciliation-toolbar">
            <div className="file-summary"><span className="file-icon" aria-hidden="true">XLS</span><div><strong title={sheet.fileName}>{sheet.fileName}</strong><span>{"共 "+sheet.rows.length+" 条记录 · 当前显示 "+shown.length+" 条"}</span></div></div>
            <div className="table-controls">
              <label>区域<select value={region} onChange={event=>setRegion(event.target.value)}><option>{T.all}</option>{regions.map(item=><option key={item}>{item}</option>)}</select></label>
              <label>黄色标记<select value={stripeFilter} onChange={event=>setStripeFilter(event.target.value as "all"|"review")}><option value="all">全部</option><option value="review">仅需复核</option></select></label>
              <label className="search-control"><span className="sr-only">搜索客户、负责人或区域</span><input value={searchInput} placeholder="搜索客户、负责人或区域" onChange={event=>setSearchInput(event.target.value)} /></label>
              <button type="button" className="toolbar-outline" onClick={()=>setColumnMenuOpen(open=>!open)} aria-expanded={columnMenuOpen}>列设置{hiddenColumns.length>0?"（"+hiddenColumns.length+"）":""}</button>
              <button type="button" className="toolbar-ghost" onClick={()=>{setRegion(T.all);setStripeFilter("all");setSearchInput("");setColumnFilters({});setFilterColumns([]);}}>清空筛选</button>
            </div>
            {columnMenuOpen&&<div className="column-menu" role="dialog" aria-label="列设置"><strong>显示列</strong>{sheet.headers.map((header,index)=><label key={index}><input type="checkbox" checked={!hiddenColumns.includes(index)} onChange={()=>hiddenColumns.includes(index)?setHiddenColumns(columns=>columns.filter(column=>column!==index)):setHiddenColumns(columns=>[...columns,index])}/>{tableHeader(header)}</label>)}</div>}
          </div>
          {(hiddenColumns.length>0||salesHidden)&&<div className="hidden-columns">已隐藏：{hiddenColumns.map(i=><button key={i} type="button" onClick={()=>setHiddenColumns(columns=>columns.filter(column=>column!==i))}>显示“{sheet.headers[i]}”</button>)}{salesHidden&&<button type="button" onClick={()=>setSalesHidden(false)}>显示“{T.sales}”</button>}</div>}
          {filterColumn!==null&&<div className="column-filter"><b>筛选“{sheet.headers[filterColumn]}”</b><input autoFocus value={columnFilters[filterColumn]??""} placeholder="输入筛选内容" onChange={event=>setColumnFilters(filters=>({...filters,[filterColumn!]:event.target.value}))}/><button onClick={()=>setColumnFilters(filters=>({...filters,[filterColumn!]:""}))}>清除</button><button onClick={()=>setFilterColumn(null)}>关闭</button></div>}
          <div className="table-scroll local-table" aria-busy={!sheet}>
            <table>
              <thead><tr>{sheet.headers.map((header,index)=>!hiddenColumns.includes(index)&&<th key={index} scope="col" style={columnStyle(index)} className={[tableColumnHeadingClass(header),index===0?"sticky-index":"",String(header).includes("账套")?"sticky-account":"",String(header)===T.customer?"sticky-customer":""].filter(Boolean).join(" ")}><span>{tableHeader(header)}</span><button type="button" className={"column-filter-icon "+(filterColumns.includes(index)?"active":"")} aria-label={"筛选 "+tableHeader(header)} onClick={()=>setFilterColumn(index)}>⌄</button><button type="button" className="column-resize-handle" aria-label={"调整 "+tableHeader(header)+" 列宽"} onPointerDown={event=>startColumnResize(event,index)}/></th>)}{!salesHidden&&<th scope="col" className="sales-heading sticky-action"><span>{T.sales}</span><button type="button" className="column-filter-icon" aria-label="隐藏销售填写列" onClick={()=>setSalesHidden(true)}>⋮</button></th>}</tr></thead>
              <tbody>{pagedRows.length?pagedRows.map(({row,id})=>{const customerAmount=row[customerBookIndex]; const hasCustomerBook=hasValue(customerAmount); return <tr key={id} className={[hasCustomerBook&&num(row[index(T.difference)])!==0?"has-difference":"",hasCustomerBook&&needsDifferenceStripe(sheet,id,num(row[index(T.difference)]))?"has-history-difference":""].filter(Boolean).join(" ")}>{sheet.headers.map((header,index)=>!hiddenColumns.includes(index)&&<td key={index} style={columnStyle(index)} className={cellClass(header,index)}>{String(header).includes("是否对清")?<span className={"status-badge "+clearedBadgeClass(row[index])}>{String(row[index]??"—")}</span>:<span className={"cell-value "+(String(header)===T.difference&&!hasCustomerBook?"is-empty-money":"")} title={String(row[index]??"")}>{displayTableValue(header,row[index],customerAmount)}</span>}</td>)}{!salesHidden&&<td className="sticky-action"><button className="fill-button" type="button" onClick={()=>open(id)}>{T.fill}</button></td>}</tr>}):<tr><td className="table-empty" colSpan={sheet.headers.length+1}>暂无符合条件的对账记录<button type="button" onClick={()=>{setRegion(T.all);setSearchInput("");setColumnFilters({});}}>清空筛选</button></td></tr>}</tbody>
            </table>
          </div>
          <div className="table-pagination"><span>共 {shown.length} 条，第 {page} / {pageCount} 页</span><div><button type="button" disabled={page<=1} onClick={()=>setPage(current=>Math.max(1,current-1))}>上一页</button><span>{page}</span><button type="button" disabled={page>=pageCount} onClick={()=>setPage(current=>Math.min(pageCount,current+1))}>下一页</button><select aria-label="每页条数" value={pageSize} onChange={event=>setPageSize(Number(event.target.value))}><option value={10}>每页 10 条</option><option value={20}>每页 20 条</option><option value={50}>每页 50 条</option></select></div></div>
        </>}
      </section>
      {active!==null && sheet && <div className="modal-backdrop"><section className="sales-modal">
        <div className="sales-modal-sticky"><button type="button" className="modal-close" aria-label="关闭销售填写" onClick={()=>setActive(null)}>{"\u00d7"}</button><p className="eyebrow">{T.sales}</p><p className="sales-account">{"\u8d26\u5957\uff1a"}{String(sheet.rows[active][accountIndex]??"\u2014")}</p><h2>{`${String(sheet.rows[active][customerIndex]??T.customerFallback)} ${T.detail}`}</h2>
        <div className="amount-bar"><span>{`${T.company}\uff1a`}<strong>{money(company)}</strong></span><span>{`${T.difference}\uff1a`}<strong>{money(difference)}</strong></span><span className={isClear?"clear":"unclear"}>{isClear?T.clear:T.uncleared}</span></div>
        <div className="customer-save-row"><TextField label={T.customerBook} value={form.customerAmount} type="number" onChange={value=>setForm({...form,customerAmount:value})}/><TextField label={RESPONSIBLE_HEADER} value={form.responsible} onChange={updateResponsible}/><button className="save-button top-save-button" onClick={commit}>{T.save}</button></div>
        </div>
        <div className="sales-modal-body"><div className="detail-grid"><InvoiceGroup title={T.transitReview} entries={form.transit} requiresReview={true} ledgerKeys={matchingLedgerKeys} ledgerLookup={ledgerLookup} setEntries={entries=>setForm({...form,transit:entries})}/><InvoiceGroup title={T.returnReview} entries={form.returned} requiresReview={true} ledgerKeys={matchingLedgerKeys} ledgerLookup={ledgerLookup} setEntries={entries=>setForm({...form,returned:entries})}/><InvoiceGroup title={T.lostReview} entries={form.lost} requiresReview={true} ledgerKeys={matchingLedgerKeys} ledgerLookup={ledgerLookup} setEntries={entries=>setForm({...form,lost:entries})}/><InvoiceGroup title={T.instrumentReview} entries={form.instrument} requiresReview={true} ledgerKeys={matchingLedgerKeys} ledgerLookup={ledgerLookup} setEntries={entries=>setForm({...form,instrument:entries})}/><InvoiceGroup title={T.otherInvoice} entries={form.otherInvoice} requiresReview={true} ledgerKeys={matchingLedgerKeys} ledgerLookup={ledgerLookup} setEntries={entries=>setForm({...form,otherInvoice:entries})}/><OtherGroup entries={form.other} setEntries={entries=>setForm({...form,other:entries})} onPreview={setPreviewImage}/></div>
        <div className="amount-bar evidence"><span>{T.total}<strong>{money(total)}</strong></span><span>{T.compare}<strong>{Math.abs(total-difference)<.01?T.same:T.different}</strong></span></div>
        <div className="detail-grid two"><div><TextField label={T.badDebt} value={form.badDebt} type="number" onChange={value=>setForm({...form,badDebt:value})}/><TextField label={"死账原因"} value={form.badDebtReason} onChange={value=>setForm({...form,badDebtReason:value})}/></div><div><TextField label={T.adjustment} value={form.adjustment} type="number" onChange={value=>setForm({...form,adjustment:value})}/><TextField label={"调账原因"} value={form.adjustmentReason} onChange={value=>setForm({...form,adjustmentReason:value})}/></div><TextField label={"\u89e3\u51b3\u65f6\u95f4"} value={form.resolutionTime} type="date" onChange={value=>setForm({...form,resolutionTime:value})}/><TextField label={"\u89e3\u51b3\u65b9\u6848"} value={form.resolutionSolution} onChange={value=>setForm({...form,resolutionSolution:value})}/></div></div>
      </section></div>}
      {previewImage&&<div className="image-lightbox" role="dialog" aria-label="图片预览" onClick={()=>setPreviewImage(null)}><div onClick={event=>event.stopPropagation()}><button type="button" className="modal-close" onClick={()=>setPreviewImage(null)}>×</button><img src={previewImage} alt="其他（无发票）图片附件预览"/></div></div>}
    </>
  );

  return <><section className="local-tool"><div className="local-toolbar"><div><p className="eyebrow">{T.local}</p><h2>{T.importTitle}</h2><p>{T.importHint}</p></div><div className="toolbar-actions"><label className="file-button">{T.import}<input type="file" accept=".xlsx,.xls" onChange={importFile}/></label>{sheet&&<button className="clear-button" onClick={clearData}>{T.clearData}</button>}</div></div>{message&&<p className="import-message">{message}</p>}{!sheet?<div className="local-empty"><strong>{T.needImport}</strong></div>:<><div className="local-summary"><div><strong>{sheet.fileName}</strong><span>{`\u5171 ${sheet.rows.length} \u6761\u8bb0\u5f55`}</span></div><label>{`\u6309${T.region}\u67e5\u770b`}<select value={region} onChange={e=>setRegion(e.target.value)}><option>{T.all}</option>{regions.map(item=><option key={item}>{item}</option>)}</select></label><span>{`\u5f53\u524d\u663e\u793a ${shown.length} \u6761`}</span></div><div className="table-scroll local-table"><table><thead><tr>{sheet.headers.map((header,i)=><th key={i}>{header}</th>)}<th>{T.sales}</th></tr></thead><tbody>{shown.map(({row,id})=><tr key={id}>{sheet.headers.map((_,i)=><td key={i}>{String(row[i]??"")}</td>)}<td><button className="fill-button" onClick={()=>open(id)}>{T.fill}</button></td></tr>)}</tbody></table></div></>}</section>{active!==null&&sheet&&<div className="modal-backdrop"><section className="sales-modal"><button className="modal-close" onClick={()=>setActive(null)}>×</button><p className="eyebrow">{T.sales}</p><h2>{`${String(sheet.rows[active][customerIndex]??T.customerFallback)} ${T.detail}`}</h2><div className="amount-bar"><span>{`${T.company}：`}<strong>{money(company)}</strong></span><span>{`${T.difference}：`}<strong>{money(difference)}</strong></span><span className={isClear?"clear":"unclear"}>{isClear?T.clear:T.uncleared}</span></div><TextField label={T.customerBook} value={form.customerAmount} type="number" onChange={value=>setForm({...form,customerAmount:value})}/><div className="detail-grid"><InvoiceGroup title={T.transitReview} entries={form.transit} requiresReview={true} ledgerKeys={ledgerKeys} setEntries={entries=>setForm({...form,transit:entries})}/><InvoiceGroup title={T.returnReview} entries={form.returned} requiresReview={true} ledgerKeys={ledgerKeys} setEntries={entries=>setForm({...form,returned:entries})}/><InvoiceGroup title={T.otherInvoice} entries={form.otherInvoice} requiresReview={false} ledgerKeys={ledgerKeys} setEntries={entries=>setForm({...form,otherInvoice:entries})}/><OtherGroup entries={form.other} setEntries={entries=>setForm({...form,other:entries})}/></div><div className="amount-bar evidence"><span>{T.total}<strong>{money(total)}</strong></span><span>{T.compare}<strong>{Math.abs(total-difference)<.01?T.same:T.different}</strong></span></div><div className="detail-grid two"><TextField label={T.badDebt} value={form.badDebt} type="number" onChange={value=>setForm({...form,badDebt:value})}/><TextField label={T.adjustment} value={form.adjustment} type="number" onChange={value=>setForm({...form,adjustment:value})}/></div><button className="save-button" onClick={commit}>{T.save}</button></section></div>}</>;
}

function TextField({label,value,onChange,type="text",onBlur}:{label:string;value:string;onChange:(value:string)=>void;type?:string;onBlur?:()=>void}) { return <label className="field"><span>{label}</span><input type={type} step={type==="number"?"0.01":undefined} value={value} onChange={e=>onChange(e.target.value)} onBlur={onBlur}/></label>; }
async function cropInvoiceRows(file:File) { return new Promise<HTMLCanvasElement[]>((resolve,reject)=>{ const url=URL.createObjectURL(file); const image=new Image(); image.onload=()=>{ const sourceWidth=image.naturalWidth; const sourceHeight=image.naturalHeight; const source=document.createElement("canvas"); source.width=sourceWidth; source.height=sourceHeight; const sourceContext=source.getContext("2d",{willReadFrequently:true}); if(!sourceContext){URL.revokeObjectURL(url);reject(new Error("canvas"));return;} sourceContext.drawImage(image,0,0); const pixels=sourceContext.getImageData(0,0,sourceWidth,sourceHeight).data; const isDark=(x:number,y:number)=>{const at=(y*sourceWidth+x)*4;return pixels[at]<75&&pixels[at+1]<75&&pixels[at+2]<75;}; const vertical:number[]=[]; for(let x=0;x<sourceWidth;x++){let dark=0;for(let y=2;y<sourceHeight-2;y++)if(isDark(x,y))dark++;if(dark>sourceHeight*.55)vertical.push(x);} const columns=vertical.filter((x,index)=>index===0||x-vertical[index-1]>2); const left=columns.length>=5?columns[3]+2:Math.round(sourceWidth*.60); const right=columns.length>=5?columns[4]-2:Math.round(sourceWidth*.89); const width=right-left; const lines:number[]=[]; for(let y=0;y<sourceHeight;y++){let dark=0;for(let x=left+2;x<right-2;x++)if(isDark(x,y))dark++;if(dark>width*.58)lines.push(y);} const detected=lines.filter((y,index)=>index===0||y-lines[index-1]>2); const rowHeight=detected.length>1?detected[1]-detected[0]:0; const boundaries=detected.length>1?[Math.max(0,detected[0]-rowHeight),...detected]:detected; const ranges=boundaries.slice(0,-1).map((top,index)=>[top+2,boundaries[index+1]-2] as const).filter(([top,bottom])=>bottom-top>12); const rows=(ranges.length>1?ranges:[[0,sourceHeight]]).map(([top,bottom])=>{const scale=3;const canvas=document.createElement("canvas");canvas.width=width*scale;canvas.height=(bottom-top)*scale;const context=canvas.getContext("2d");if(!context)throw new Error("canvas");context.filter="grayscale(1) contrast(3)";context.drawImage(image,left,top,width,bottom-top,0,0,canvas.width,canvas.height);return canvas;}); URL.revokeObjectURL(url); resolve(rows); }; image.onerror=()=>{URL.revokeObjectURL(url);reject(new Error("image"));}; image.src=url; }); }
const extractInvoiceNumbers=(text:string)=>text.split(/\r?\n/).map(line=>line.replace(/\D/g,"")).filter(digits=>digits.length>=7);
function InvoiceGroup({title,entries,requiresReview,ledgerKeys,ledgerLookup,setEntries}:{title:string;entries:InvoiceEntry[];requiresReview:boolean;ledgerKeys:Set<string>|null;ledgerLookup:LedgerLookup;setEntries:(entries:InvoiceEntry[])=>void}) {
  const [choices,setChoices]=useState<Record<number,string[]>>({});
  const [expanded,setExpanded]=useState(true);
  const [photoBusy,setPhotoBusy]=useState(false);
  const [photoStatus,setPhotoStatus]=useState("");
  const [photoInvoices,setPhotoInvoices]=useState<string[]>([]);
  const update=(index:number,field:keyof InvoiceEntry,value:string)=>setEntries(entries.map((entry,i)=>i===index?{...entry,[field]:value}:entry));
  const remove=(index:number)=>setEntries(entries.length===1?[blankInvoice()]:entries.filter((_,i)=>i!==index));
  const autoFill=(index:number)=>{if(!requiresReview)return;const match=findLedgerMatch(entries[index]?.invoice??"",ledgerLookup,ledgerKeys);if(!match)return;setEntries(entries.map((entry,i)=>i===index?{...entry,date:match.dates.length===1?match.dates[0]:entry.date,amount:match.amount.toFixed(2)}:entry));setChoices(current=>({...current,[index]:match.dates.length>1?match.dates:[]}));};
  const recognizePhotos=async(files:File[])=>{if(!files.length)return;setPhotoBusy(true);setPhotoStatus("正在通过表格线定位“发票号码”单元格并逐行识别…");setPhotoInvoices([]);let worker:Awaited<ReturnType<typeof import("tesseract.js").createWorker>>|null=null;try{const {createWorker}=await import("tesseract.js");worker=await createWorker("eng");await worker.setParameters({tessedit_char_whitelist:"0123456789",tessedit_pageseg_mode:"7"});const numbers=new Set<string>();let rows=0;for(const file of files){for(const row of await cropInvoiceRows(file)){const result=await worker.recognize(row);for(const invoice of extractInvoiceNumbers(result.data.text)){numbers.add(invoice);rows++;}}}const found=[...numbers];const verified=found.filter(invoice=>findLedgerMatch(invoice,ledgerLookup,ledgerKeys)).length;setPhotoInvoices(found);setPhotoStatus(found.length?`已识别 ${rows} 行、${found.length} 个不重复发票号，其中 ${verified} 个可由往来明细自动补全。`:'未识别到发票号，请确认截图包含“发票号码”整列。');}catch{setPhotoStatus("照片识别失败，请使用包含发票号码整列的清晰截图后重试。");}finally{if(worker)await worker.terminate();setPhotoBusy(false);}};
  const importPhotos=()=>{const existing=new Set(entries.map(entry=>entry.invoice.trim()).filter(Boolean));const fresh=photoInvoices.filter(invoice=>!existing.has(invoice));if(!fresh.length){setPhotoStatus("识别到的发票号已在当前明细中，不重复导入。");return;}const next=[...entries.filter(anyInvoice),...fresh.map(invoice=>{const match=findLedgerMatch(invoice,ledgerLookup,ledgerKeys);return {invoice,date:match?.dates.length===1?match.dates[0]:"",amount:match?match.amount.toFixed(2):"",note:"照片识别导入"};})];setEntries(next.length?next:[blankInvoice()]);setPhotoInvoices([]);setPhotoStatus(`已导入 ${fresh.length} 笔；多日期发票请在下方确认开票日期。`);};
  return <div className="detail-box"><div className="detail-box-heading"><h3>{title}</h3><button type="button" className="collapse-button" onClick={()=>setExpanded(value=>!value)}>{expanded?"收起":"展开"}</button></div>{expanded&&<>{requiresReview&&<div className="photo-import"><label className="photo-import-button">{photoBusy?"正在识别…":"导入识别照片"}<input type="file" accept="image/*" multiple disabled={photoBusy} onChange={event=>{void recognizePhotos(Array.from(event.target.files??[]));event.target.value="";}}/></label><span>仅在本机识别；发票号会用往来明细自动补全日期和金额。</span>{photoStatus&&<p>{photoStatus}</p>}{photoInvoices.length>0&&<div className="photo-result"><span>{photoInvoices.join("、")}</span><button type="button" onClick={importPhotos}>导入识别结果</button></div>}</div>}{entries.map((entry,index)=>{ const has=anyInvoice(entry); const matched=validLedgerEntry(entry,ledgerKeys); const status=!has?"":!entry.date||!entry.invoice||entry.amount===""?T.incomplete:!ledgerKeys?T.loading:matched?T.matched:T.missing; return <div className="invoice-entry" key={index}><div className="entry-head"><strong>{`\u7b2c ${index+1} \u7b14`}</strong>{entries.length>1&&<button type="button" className="remove-entry" onClick={()=>remove(index)}>{T.remove}</button>}</div><TextField label={T.invoiceDate} value={entry.date} type="date" onChange={value=>update(index,"date",value)}/><TextField label={T.invoice} value={entry.invoice} onChange={value=>update(index,"invoice",value)} onBlur={()=>autoFill(index)}/><TextField label={T.amount} value={entry.amount} type="number" onChange={value=>update(index,"amount",value)}/>{choices[index]?.length>1&&<div className="invoice-choices"><span>金额已自动累计，请确认开票日期：</span>{choices[index].map(date=><button type="button" key={date} onClick={()=>{update(index,"date",date);setChoices(current=>({...current,[index]:[]}));}}>{date}</button>)}</div>}<TextField label={T.reason} value={entry.note} onChange={value=>update(index,"note",value)}/>{requiresReview&&<p className={`ledger-check ${has&&ledgerKeys?(matched?"matched":"not-matched"):""}`}>{status||"填写完整发票号后将自动带出日期和金额"}</p>}</div>; })}<button type="button" className="add-entry" onClick={()=>setEntries([...entries,blankInvoice()])}>{T.add}</button></>}</div>; }
function OtherGroup({entries,setEntries,onPreview}:{entries:OtherEntry[];setEntries:(entries:OtherEntry[])=>void;onPreview:(image:string)=>void}) { const update=(index:number,field:keyof OtherEntry,value:string)=>setEntries(entries.map((entry,i)=>i===index?{...entry,[field]:value}:entry)); const remove=(index:number)=>setEntries(entries.length===1?[blankOther()]:entries.filter((_,i)=>i!==index)); const addImage=async(index:number,file?:File)=>{if(!file)return;if(!file.type.startsWith("image/")){window.alert("请选择图片文件。");return;}if(file.size>2*1024*1024){window.alert("图片不能超过 2MB。");return;}const reader=new FileReader();reader.onload=()=>update(index,"image",String(reader.result??""));reader.readAsDataURL(file);};const [expanded,setExpanded]=useState(true);return <div className="detail-box"><div className="detail-box-heading"><h3>{T.otherNoInvoice}</h3><button type="button" className="collapse-button" onClick={()=>setExpanded(value=>!value)}>{expanded?"收起":"展开"}</button></div>{expanded&&<>{entries.map((entry,index)=><div className="invoice-entry" key={index}><div className="entry-head"><strong>{`\u7b2c ${index+1} \u7b14`}</strong>{entries.length>1&&<button type="button" className="remove-entry" onClick={()=>remove(index)}>{T.remove}</button>}</div><TextField label={T.amount} value={entry.amount} type="number" onChange={value=>update(index,"amount",value)}/><TextField label={T.reason} value={entry.note} onChange={value=>update(index,"note",value)}/><label className="image-field"><span>图片附件</span><input type="file" accept="image/*" onChange={event=>{void addImage(index,event.target.files?.[0]);event.target.value="";}}/>{entry.image&&<div className="image-preview"><button type="button" className="image-open" onClick={()=>onPreview(entry.image!)} aria-label={`查看其他（无发票）第 ${index+1} 笔图片`}><img src={entry.image} alt={`其他（无发票）第 ${index+1} 笔附件`}/><span>点击查看</span></button><button type="button" className="remove-entry" onClick={()=>update(index,"image","")}>删除图片</button></div>}</label></div>)}<button type="button" className="add-entry" onClick={()=>setEntries([...entries,blankOther()])}>{T.add}</button></>}</div>; }
